9	const DEFAULT_BRIDGE_TOKEN_BYTES = 24;
10	const DEFAULT_BRIDGE_POLL_INTERVAL_MS = 100;
11	const DEFAULT_BRIDGE_RESPONSE_TIMEOUT_MS = 30_000;
12	const DEFAULT_BRIDGE_STOP_TIMEOUT_MS = 2_000;
13	const DEFAULT_BRIDGE_MAX_QUEUE_DEPTH = 64;
14	const DEFAULT_BRIDGE_MAX_BODY_BYTES = 256 * 1024;
15	const REMOTE_WRITE_BASE64_CHUNK_SIZE = 32 * 1024;
16	const SANDBOX_CALLBACK_BRIDGE_ENTRYPOINT = "paperclip-bridge-server.mjs";
17	
18	export const DEFAULT_SANDBOX_CALLBACK_BRIDGE_MAX_BODY_BYTES = DEFAULT_BRIDGE_MAX_BODY_BYTES;
