25	export const DEFAULT_SANDBOX_CALLBACK_BRIDGE_ROUTE_ALLOWLIST: readonly SandboxCallbackBridgeRouteRule[] = [
26	  { method: "GET", path: /^\/api\/agents\/me$/ },
27	  { method: "GET", path: /^\/api\/issues\/[^/]+\/heartbeat-context$/ },
28	  { method: "GET", path: /^\/api\/issues\/[^/]+\/comments(?:\/[^/]+)?$/ },
29	  { method: "GET", path: /^\/api\/issues\/[^/]+\/documents(?:\/[^/]+)?$/ },
30	  { method: "POST", path: /^\/api\/issues\/[^/]+\/checkout$/ },
31	  { method: "POST", path: /^\/api\/issues\/[^/]+\/comments$/ },
32	  { method: "POST", path: /^\/api\/issues\/[^/]+\/interactions(?:\/[^/]+)?$/ },
33	  { method: "PATCH", path: /^\/api\/issues\/[^/]+$/ },
34	] as const;
