103	function shellQuote(value: string) {
104	  return `'${value.replace(/'/g, `'"'"'`)}'`;
105	}
106	
107	function normalizeMethod(value: string | null | undefined): string {
108	  return typeof value === "string" && value.trim().length > 0 ? value.trim().toUpperCase() : "GET";
109	}
110	
111	function normalizeTimeoutMs(value: number | null | undefined, fallback: number): number {
112	  return typeof value === "number" && Number.isFinite(value) && value > 0 ? Math.trunc(value) : fallback;
113	}
114	
115	function toBuffer(bytes: Buffer | Uint8Array | ArrayBuffer): Buffer {
116	  if (Buffer.isBuffer(bytes)) return bytes;
117	  if (bytes instanceof ArrayBuffer) return Buffer.from(bytes);
118	  return Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength);
119	}
