121	function buildRunnerFailureMessage(action: string, result: RunProcessResult): string {
122	  const stderr = result.stderr.trim();
123	  const stdout = result.stdout.trim();
124	  const detail = stderr || stdout;
125	  if (result.timedOut) {
126	    return `${action} timed out${detail ? `: ${detail}` : ""}`;
127	  }
128	  return `${action} failed with exit code ${result.exitCode ?? "null"}${detail ? `: ${detail}` : ""}`;
129	}
