131	async function runShell(
132	  runner: CommandManagedRuntimeRunner,
133	  cwd: string,
134	  script: string,
135	  timeoutMs: number,
136	): Promise<RunProcessResult> {
137	  return await runner.execute({
138	    command: "sh",
139	    args: ["-lc", script],
140	    cwd,
141	    timeoutMs,
142	  });
143	}
144	
145	function requireSuccessfulResult(action: string, result: RunProcessResult): RunProcessResult {
146	  if (!result.timedOut && result.exitCode === 0) return result;
147	  throw new Error(buildRunnerFailureMessage(action, result));
148	}
149	
150	function base64Chunks(body: string): string[] {
151	  const out: string[] = [];
152	  for (let offset = 0; offset < body.length; offset += REMOTE_WRITE_BASE64_CHUNK_SIZE) {
153	    out.push(body.slice(offset, offset + REMOTE_WRITE_BASE64_CHUNK_SIZE));
154	  }
155	  return out;
156	}
