162	export function authorizeSandboxCallbackBridgeRequestWithRoutes(
163	  request: Pick<SandboxCallbackBridgeRequest, "method" | "path">,
164	  routes: readonly SandboxCallbackBridgeRouteRule[] = DEFAULT_SANDBOX_CALLBACK_BRIDGE_ROUTE_ALLOWLIST,
165	): string | null {
166	  const method = normalizeMethod(request.method);
167	  return routes.some((route) => route.method === method && route.path.test(request.path))
168	    ? null
169	    : `Route not allowed: ${method} ${request.path}`;
170	}
