172	export function sanitizeSandboxCallbackBridgeHeaders(
173	  headers: Record<string, string>,
174	  allowlist: readonly string[] = DEFAULT_SANDBOX_CALLBACK_BRIDGE_HEADER_ALLOWLIST,
175	): Record<string, string> {
176	  const allowed = new Set(allowlist.map((header) => header.toLowerCase()));
177	  return Object.fromEntries(
178	    Object.entries(headers).filter(([key]) => allowed.has(key.toLowerCase())),
179	  );
180	}
