210	    PAPERCLIP_BRIDGE_POLL_INTERVAL_MS: String(
211	      normalizeTimeoutMs(input.pollIntervalMs, DEFAULT_BRIDGE_POLL_INTERVAL_MS),
212	    ),
213	    PAPERCLIP_BRIDGE_RESPONSE_TIMEOUT_MS: String(
214	      normalizeTimeoutMs(input.responseTimeoutMs, DEFAULT_BRIDGE_RESPONSE_TIMEOUT_MS),
215	    ),
216	    PAPERCLIP_BRIDGE_MAX_QUEUE_DEPTH: String(
217	      normalizeTimeoutMs(input.maxQueueDepth, DEFAULT_BRIDGE_MAX_QUEUE_DEPTH),
218	    ),
219	    PAPERCLIP_BRIDGE_MAX_BODY_BYTES: String(
220	      normalizeTimeoutMs(input.maxBodyBytes, DEFAULT_BRIDGE_MAX_BODY_BYTES),
221	    ),
222	  };
223	}
