225	export async function createSandboxCallbackBridgeAsset(): Promise<SandboxCallbackBridgeAsset> {
226	  const localDir = await fs.mkdtemp(path.join(os.tmpdir(), "paperclip-bridge-asset-"));
227	  const entrypoint = path.join(localDir, SANDBOX_CALLBACK_BRIDGE_ENTRYPOINT);
228	  await fs.writeFile(entrypoint, getSandboxCallbackBridgeServerSource(), "utf8");
229	  return {
230	    localDir,
231	    entrypoint,
232	    cleanup: async () => {
233	      await fs.rm(localDir, { recursive: true, force: true }).catch(() => undefined);
234	    },
235	  };
236	}
