238	export function createFileSystemSandboxCallbackBridgeQueueClient(): SandboxCallbackBridgeQueueClient {
239	  return {
240	    makeDir: async (remotePath) => {
241	      await fs.mkdir(remotePath, { recursive: true });
242	    },
243	    listJsonFiles: async (remotePath) => {
244	      const entries = await fs.readdir(remotePath, { withFileTypes: true }).catch(() => []);
245	      return entries
246	        .filter((entry) => entry.isFile() && entry.name.endsWith(".json"))
247	        .map((entry) => entry.name)
248	        .sort((left, right) => left.localeCompare(right));
249	    },
250	    readTextFile: async (remotePath) => await fs.readFile(remotePath, "utf8"),
251	    writeTextFile: async (remotePath, body) => {
252	      await fs.mkdir(path.posix.dirname(remotePath), { recursive: true });
253	      await fs.writeFile(remotePath, body, "utf8");
254	    },
255	    rename: async (fromPath, toPath) => {
256	      await fs.mkdir(path.posix.dirname(toPath), { recursive: true });
257	      await fs.rename(fromPath, toPath);
258	    },
259	    remove: async (remotePath) => {
260	      await fs.rm(remotePath, { recursive: true, force: true }).catch(() => undefined);
261	    },
262	  };
263	}
