334	async function writeBridgeResponse(
335	  client: SandboxCallbackBridgeQueueClient,
336	  responsePath: string,
337	  response: SandboxCallbackBridgeResponse,
338	) {
339	  const tempPath = `${responsePath}.tmp`;
340	  await client.writeTextFile(tempPath, `${JSON.stringify(response)}\n`);
341	  await client.rename(tempPath, responsePath);
342	}
