515	export async function startSandboxCallbackBridgeServer(input: {
516	  runner: CommandManagedRuntimeRunner;
517	  remoteCwd: string;
518	  assetRemoteDir: string;
519	  queueDir: string;
520	  bridgeToken: string;
521	  bridgeAsset?: SandboxCallbackBridgeAsset | null;
522	  host?: string;
523	  port?: number | null;
524	  pollIntervalMs?: number | null;
525	  responseTimeoutMs?: number | null;
526	  timeoutMs?: number | null;
527	  nodeCommand?: string;
528	  maxQueueDepth?: number | null;
529	  maxBodyBytes?: number | null;
530	}): Promise<StartedSandboxCallbackBridgeServer> {
531	  const timeoutMs = normalizeTimeoutMs(input.timeoutMs, DEFAULT_BRIDGE_RESPONSE_TIMEOUT_MS);
532	  const directories = sandboxCallbackBridgeDirectories(input.queueDir);
533	  const remoteEntrypoint = path.posix.join(input.assetRemoteDir, SANDBOX_CALLBACK_BRIDGE_ENTRYPOINT);
534	  if (input.bridgeAsset) {
535	    const assetClient = createCommandManagedSandboxCallbackBridgeQueueClient({
536	      runner: input.runner,
537	      remoteCwd: input.remoteCwd,
538	      timeoutMs,
539	    });
540	    await assetClient.makeDir(input.assetRemoteDir);
541	    const entrypointSource = await fs.readFile(input.bridgeAsset.entrypoint, "utf8");
542	    await assetClient.writeTextFile(remoteEntrypoint, entrypointSource);
543	  }
544	  const env = buildSandboxCallbackBridgeEnv({
545	    queueDir: input.queueDir,
546	    bridgeToken: input.bridgeToken,
547	    host: input.host,
548	    port: input.port,
549	    pollIntervalMs: input.pollIntervalMs,
550	    responseTimeoutMs: input.responseTimeoutMs,
551	    maxQueueDepth: input.maxQueueDepth,
552	    maxBodyBytes: input.maxBodyBytes,
553	  });
554	  const nodeCommand = input.nodeCommand?.trim() || "node";
555	  const startResult = await input.runner.execute({
556	    command: "sh",
557	    args: [
558	      "-lc",
559	      [
560	        `mkdir -p ${shellQuote(directories.requestsDir)} ${shellQuote(directories.responsesDir)} ${shellQuote(directories.logsDir)}`,
561	        `rm -f ${shellQuote(directories.readyFile)} ${shellQuote(directories.pidFile)}`,
562	        `nohup env ${Object.entries(env).map(([key, value]) => `${key}=${shellQuote(value)}`).join(" ")} ` +
563	          `${shellQuote(nodeCommand)} ${shellQuote(remoteEntrypoint)} ` +
564	          `>> ${shellQuote(directories.logFile)} 2>&1 < /dev/null &`,
565	        "pid=$!",
566	        `printf '%s\\n' \"$pid\" > ${shellQuote(directories.pidFile)}`,
567	        "printf '{\"pid\":%s}\\n' \"$pid\"",
568	      ].join("\n"),
569	    ],
