661	const queueDir = process.env.PAPERCLIP_BRIDGE_QUEUE_DIR;
662	const bridgeToken = process.env.PAPERCLIP_BRIDGE_TOKEN;
663	const host = process.env.PAPERCLIP_BRIDGE_HOST || "127.0.0.1";
664	const port = Number(process.env.PAPERCLIP_BRIDGE_PORT || "0");
665	const pollIntervalMs = Number(process.env.PAPERCLIP_BRIDGE_POLL_INTERVAL_MS || "100");
666	const responseTimeoutMs = Number(process.env.PAPERCLIP_BRIDGE_RESPONSE_TIMEOUT_MS || "30000");
667	const maxQueueDepth = Number(process.env.PAPERCLIP_BRIDGE_MAX_QUEUE_DEPTH || "${DEFAULT_BRIDGE_MAX_QUEUE_DEPTH}");
668	const maxBodyBytes = Number(process.env.PAPERCLIP_BRIDGE_MAX_BODY_BYTES || "${DEFAULT_BRIDGE_MAX_BODY_BYTES}");
669	const allowedHeaders = new Set(${JSON.stringify([...DEFAULT_SANDBOX_CALLBACK_BRIDGE_HEADER_ALLOWLIST])});
670	
671	if (!queueDir || !bridgeToken) {
672	  throw new Error("PAPERCLIP_BRIDGE_QUEUE_DIR and PAPERCLIP_BRIDGE_TOKEN are required.");
673	}
674	
675	const requestsDir = path.posix.join(queueDir, "requests");
676	const responsesDir = path.posix.join(queueDir, "responses");
677	const logsDir = path.posix.join(queueDir, "logs");
678	const readyFile = path.posix.join(queueDir, "ready.json");
679	
680	function sleep(ms) {
681	  return new Promise((resolve) => setTimeout(resolve, ms));
682	}
683	
684	function normalizeHeaders(headers) {
685	  const out = {};
686	  for (const [key, value] of Object.entries(headers)) {
687	    if (value == null) continue;
688	    const normalizedKey = key.toLowerCase();
689	    if (!allowedHeaders.has(normalizedKey)) {
690	      continue;
691	    }
692	    out[normalizedKey] = Array.isArray(value) ? value.join(", ") : String(value);
693	  }
694	  return out;
695	}
696	
697	async function readBody(req) {
698	  const chunks = [];
699	  let totalBytes = 0;
700	  for await (const chunk of req) {
701	    const nextChunk = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
702	    chunks.push(nextChunk);
703	    totalBytes += nextChunk.byteLength;
704	    if (totalBytes > maxBodyBytes) {
705	      throw new Error("Bridge request body exceeded the configured size limit.");
706	    }
707	  }
708	  return Buffer.concat(chunks).toString("utf8");
709	}
